<script>(function(){const form=document.querySelector('form[action*="/provision"]');const profile=document.querySelector('select[name=profile]');const button=document.getElementById('executeProvisioning');const reason=document.getElementById('provisioningLockReason');function gate(){const option=profile.options[profile.selectedIndex];const models=(option?.dataset.models||'').split(',').map(v=>v.trim().toLowerCase());const model=(form.dataset.deviceModel||'').trim().toLowerCase();const ok=!!model&&models.includes(model)&&form.dataset.sshEnabled==='1'&&form.dataset.provisioningEnabled==='1'&&form.dataset.credentialsConfigured==='1';button.disabled=!ok;reason.textContent=ok?'Command will be sent only after you confirm the action.':'Locked: exact model match, SSH, provisioning and saved credentials are all required.'}function s(){let a=document.getElementById('vsolAction').value;document.querySelectorAll('[data-field]').forEach(e=>e.style.display='none');let m={authorize_mac:['mac'],remove_mac:['mac'],configure_pppoe:['pppoe'],configure_static_ip:['static'],enable_onu:[],disable_onu:[]};(m[a]||[]).forEach(k=>document.querySelectorAll('[data-field='+k+']').forEach(e=>e.style.display='block'));document.querySelector('input[name=onu]').required=['configure_pppoe','configure_static_ip','enable_onu','disable_onu'].includes(a);document.querySelector('input[name=mac]').required=['authorize_mac','remove_mac'].includes(a)}document.getElementById('vsolAction').addEventListener('change',s);profile.addEventListener('change',gate);s();gate()})();</script>
